{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYS_ORGANICS_NYKAA_SALES_FACT_ITEMS_INTERMEDIATE AS SELECT \"SKU_CODE\" AS SKU_CODE, \"SKU_NAME\" AS SKU_NAME, BRAND AS BRAND, SELLER_CODE, \"COMPANY_NAME\" AS COMPANY_NAME, \"SELLER_TYPE\" AS SELLER_TYPE, PLATFORM AS PLATFORM, CAST(DATE AS TIMESTAMP_NTZ) AS ORDER_DATE, CAST(MRP AS FLOAT) AS NYKAA_MRP, CAST(\"DISPLAY_PRICE\" AS FLOAT) AS DISPLAY_PRICE, CAST(\"SELLING_PRICE\" AS FLOAT) AS SELLING_PRICE, CAST(\"TOTAL_QTY\" AS NUMBER(38,0)) AS QUANTITY, CAST(\"TOTAL_ORDERS\" AS NUMBER(38,0)) AS TOTAL_ORDERS, CAST(\"TOTAL_CUSTOMERS\" AS NUMBER(38,0)) AS TOTAL_CUSTOMERS, \"CATEGORY_L1\" AS CATEGORY_L1, \"CATEGORY_L2\" AS CATEGORY_L2, \"CATEGORY_L3\" AS CATEGORY_L3 FROM RUBYSORGANICS_DB.MAPLEMONK.NYKAA_SALES_REPORT QUALIFY ROW_NUMBER() OVER ( PARTITION BY DATE, \"SKU_CODE\", PLATFORM ORDER BY 1 ) = 1; CREATE OR REPLACE TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYS_ORGANICS_NYKAA_SALES_FACT_ITEMS AS SELECT CONCAT( n.SKU_CODE, \'-\', n.ORDER_DATE, \'-\', n.PLATFORM, \'-\', n.SKU_NAME, \'-\', n.QUANTITY, \'-\', n.SELLING_PRICE ) AS ORDER_ID, UPPER(TRIM(n.SKU_NAME)) AS PRODUCT_NAME_FINAL, UPPER(CAST(n.CATEGORY_L1 AS VARCHAR)) AS PRODUCT_CATEGORY, UPPER(n.CATEGORY_L2) AS SUB_CATEGORY, UPPER(n.CATEGORY_L3) AS SUB_SUB_CATEGORY, n.SKU_CODE AS COMMONSKU, NULL AS MRP, n.* FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYS_ORGANICS_NYKAA_SALES_FACT_ITEMS_INTERMEDIATE n;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from RUBYSORGANICS_DB.information_schema.databases
            ),
            
            final as (
